from playwright.sync_api import sync_playwright
from pathlib import Path
import json,base64
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader','--autoplay-policy=no-user-gesture-required'])
 page=b.new_page(viewport={'width':900,'height':650},reduced_motion='reduce');errors=[];page.on('pageerror',lambda e:(errors.append(str(e)),print('ERROR '+str(e),flush=True)))
 page.add_init_script('window.requestAnimationFrame=()=>0');page.route('**/@vite/client',lambda r:r.fulfill(body='',content_type='application/javascript'))
 page.goto('http://127.0.0.1:5173/',wait_until='domcontentloaded',timeout=240000);page.locator('[data-mode="airplane"]').wait_for(state='visible',timeout=240000)
 page.locator('#species').select_option('female');page.locator('[data-mode="airplane"]').click();page.locator('#start').click(timeout=240000)
 page.wait_for_function('!!window.__portalQA&&__portalQA.phase==="world"||!!document.querySelector("#startup-error")?.textContent',timeout=240000,polling=100);assert not page.locator('#startup-error').text_content()
 result=page.evaluate('''()=>{const q=__portalQA,s=q.vehicle.state,b=q.data.BRIDGE;window.__render=q.renderer.render.bind(q.renderer);q.renderer.render=()=>{};return {kind:s.kind,x:s.x,z:s.z,heading:s.heading,bridge:b,controls:document.querySelector('#interact').textContent};}''');print('SPAWN '+json.dumps(result,ensure_ascii=False),flush=True)
 assert result['kind']=='airplane' and result['bridge']['startX']<result['x']<result['bridge']['endX'] and result['z']==result['bridge']['z']
 page.keyboard.press('f');assert page.evaluate('__portalQA.driving'),'F boards from the actual starting position'
 # Verify the real ground chassis at the original mainland parking, using all actual vehicle configurations.
 jumps=page.evaluate('''()=>{const q=__portalQA,out=[];for(const kind of ['scooter','sedan','suv','motorhome']){let s={kind,x:q.data.ARRIVAL.x,z:q.data.ARRIVAL.z,heading:Math.PI/2,speed:15,vx:15,vz:0,bodyY:2.5};let max=2.5,touchdowns=0;const opts={heightAt:()=>2.5,waterSurfaceAt:()=>null,ceilingAt:()=>Infinity};for(let i=0;i<360;i++){s=q.stepGroundVehicle(s,{jump:true},1/120,[],opts);max=Math.max(max,s.bodyY);if(s.landed)touchdowns++;}out.push({kind,max,touchdowns,airborne:s.airborne,bodyY:s.bodyY});}return out;}''');print('JUMPS '+json.dumps(jumps),flush=True);assert all(j['max']>4 and j['touchdowns']==1 and not j['airborne'] for j in jumps),jumps
 fits=page.evaluate('''async()=>{const q=__portalQA,{makeRiderMount,updateMountedRider,visibleRiderBounds,restoreRider}=await import('/src/rider-mount.js'),{createAirplane}=await import('/src/light-airplane.js'),model=q.characterModel,C=q.aircraftConstructors,Scene=q.scene.constructor,out=[];for(const species of ['male','female']){model.configure({species});for(const kind of ['scooter','sedan','suv','motorhome','helicopter','airplane']){const scene=new Scene(),v=kind==='airplane'?createAirplane(scene,C,{x:0,z:0},0,{heightAt:()=>0}):kind==='helicopter'?q.createHelicopter(scene,{x:0,z:0},0,{heightAt:()=>0}):q.createVehicle(scene,kind,{x:0,z:0},0,{heightAt:()=>0});const profile=makeRiderMount(model,kind,C,()=>q.poseCharacter(model,'sit'));updateMountedRider(model,v,profile,C);const bounds=visibleRiderBounds(model.root,C),e=profile.envelope,epsilon=.002;const fits=!e||bounds.min.x*profile.scale+profile.offset.x>=e.minX-epsilon&&bounds.max.x*profile.scale+profile.offset.x<=e.maxX+epsilon&&bounds.max.y*profile.scale+profile.offset.y<=e.roof+epsilon&&bounds.min.y*profile.scale+profile.offset.y>=e.floor-epsilon&&bounds.min.z*profile.scale+profile.offset.z>=e.minZ-epsilon&&bounds.max.z*profile.scale+profile.offset.z<=e.maxZ+epsilon;out.push({kind,species,scale:profile.scale,fits});v.dispose();}}model.configure({species:'female'});restoreRider(model);return out;}''');print('RIDER FIT '+json.dumps(fits),flush=True);assert all(f['fits'] for f in fits),fits
 # Pull the mouse down and accelerate along the bridge runway.
 page.evaluate('__portalQA.look(0,100)');page.keyboard.down('w');page.evaluate('for(let i=0;i<90;i++)__portalQA.advanceFlight(.1)');page.keyboard.up('w')
 flight=page.evaluate('({...__portalQA.vehicle.state})');print('TAKEOFF '+json.dumps(flight),flush=True);assert not flight['grounded'] and flight['bodyY']>15 and flight['x']<result['bridge']['endX'],flight
 page.keyboard.down('a');page.evaluate('for(let i=0;i<6;i++)__portalQA.advanceFlight(.1)');page.keyboard.up('a');left=page.evaluate('({...__portalQA.vehicle.state})');assert left['heading']>flight['heading'] and left['roll']<0,left
 page.keyboard.down('d');page.evaluate('for(let i=0;i<12;i++)__portalQA.advanceFlight(.1)');page.keyboard.up('d');right=page.evaluate('({...__portalQA.vehicle.state})');assert right['heading']<left['heading'] and right['roll']>0,right
 # Pushing the mouse up lowers the pitch command; pulling down raises it again.
 page.evaluate('__portalQA.look(0,-180);for(let i=0;i<7;i++)__portalQA.advanceFlight(.1)');lower=page.evaluate('__portalQA.vehicle.state.pitch');assert lower<right['pitch']
 page.evaluate('__portalQA.look(0,200);for(let i=0;i<20;i++)__portalQA.advanceFlight(.1)')
 image=page.evaluate('''()=>{const q=__portalQA,s=q.vehicle.state;q.renderer.shadowMap.enabled=false;q.renderer.setPixelRatio(.65);q.camera.far=1500;q.camera.updateProjectionMatrix();q.camera.position.set(s.x-12,s.bodyY+7,s.z-12);q.camera.lookAt(s.x,s.bodyY+1,s.z);window.__render(q.scene,q.camera);q.renderer.getContext().finish();return q.renderer.domElement.toDataURL('image/png');}''');Path('/tmp/camper-airplane-flight.png').write_bytes(base64.b64decode(image.split(',')[1]))
 page.keyboard.press('f');eject=page.evaluate('({driving:__portalQA.driving,state:__portalQA.skydiving,scale:__portalQA.player.scale.x})');assert not eject['driving'] and eject['state'] and not eject['state']['open'] and eject['scale']==1,eject
 page.evaluate('for(let i=0;i<30;i++)__portalQA.advanceFlight(.1)');freefall=page.evaluate('__portalQA.skydiving');assert freefall and freefall['vy']<0,freefall
 page.keyboard.press('f');assert page.evaluate('__portalQA.skydiving.open'),'second F deploys the parachute'
 page.keyboard.down('a');page.evaluate('for(let i=0;i<20;i++)__portalQA.advanceFlight(.1)');page.keyboard.up('a');open_state=page.evaluate('({...__portalQA.skydiving})');assert open_state['inflation']>.99 and open_state['vy']>-6,open_state
 image=page.evaluate('''()=>{const q=__portalQA,s=q.skydiving;q.camera.position.set(s.x+10,s.y+6,s.z-12);q.camera.lookAt(s.x,s.y+2,s.z);window.__render(q.scene,q.camera);q.renderer.getContext().finish();return q.renderer.domElement.toDataURL('image/png');}''');Path('/tmp/camper-parachute.png').write_bytes(base64.b64decode(image.split(',')[1]))
 landing=page.evaluate('''()=>{const q=__portalQA;let steps=0;while(q.skydiving&&steps++<1500)q.advanceFlight(.1);return {steps,skydiving:q.skydiving,position:q.player.position.toArray(),scale:q.player.scale.x,canopy:q.scene.getObjectByName('Player parachute').visible};}''');print('BAILOUT '+json.dumps({'eject':eject,'freefall':freefall,'open':open_state,'landing':landing}),flush=True);assert landing['skydiving'] is None and landing['scale']==1 and not landing['canopy'],landing
 assert not errors,errors
 print('PASS: 4 ground jumps, both characters fit all six vehicles, bridge takeoff/WASD/mouse, F bailout/F parachute/landing; errors0',flush=True)
